head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/

// 주권 종목코드 

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        const STD_CD = dts_List.getCellData(row, "STD_CD");
        const ISU_KOR_NM = dts_List.getCellData(row, "ISU_KOR_NM");

        $c.frame.path("../").ins_popupRtn_cdnm(STD_CD, ISU_KOR_NM);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90600.grd_Grid_OnDblClick" });
    }
};

scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90600.btn_close_onclick" });
    }
};

scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90600.dts_List_OnLoadCompleted" });
    }
};

scwin.dts_List_OnLoadError = function() {
    try {
        $c.win.alert(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90600.dts_List_OnLoadError" });
    }
};

scwin.txb_ISU_NM_onkeyup = function() {
    try {
        fn_DelChar(this);
        if (txb_ISU_NM.getValue() === "") {

        } else {
            if (window.event.keyCode === 13) {
                scwin.ins_search(txb_ISU_NM.getValue(), txb_ISUR_CD.getValue());
            } else {

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90600.txb_ISU_NM_onkeyup" });
    }
};

scwin.img_COM_NM_onclick = function() {
    try {
        ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90600.img_COM_NM_onclick" });
    }
};

scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        fn_DelChar(this);
        if (txb_ISUR_CD.getValue() === "") {

        } else {
            if (window.event.keyCode === 13) {
                scwin.ins_search(txb_ISU_NM.getValue(), txb_ISUR_CD.getValue());
            } else {

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90600.txb_ISUR_CD_onkeyup" });
    }
};

scwin.btn_search_onclick = function() {
    try {
        scwin.ins_search(txb_ISU_NM.getValue(), txb_ISUR_CD.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90600.btn_search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 주권 종목코드  조회 한다.
 ***********************************************/
scwin.ins_search = async function(isunm, isurcd) {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    txb_ISU_NM.focus();
};
